  const hasLoadedDailyReportsRef = useRef(false);
  useEffect(() => {
    try {
      const saved = localStorage.getItem('hris_daily_reports');
      if (saved) {
        setDailyReportItems(JSON.parse(saved));
      }
    } catch (e) {
      console.error('Error loading daily reports:', e);
    }
    hasLoadedDailyReportsRef.current = true;
  }, []);

  useEffect(() => {
    if (hasLoadedDailyReportsRef.current) {
      try {
        localStorage.setItem('hris_daily_reports', JSON.stringify(dailyReportItems));
      } catch (e) {
        console.error('Error saving daily reports:', e);
      }
    }
  }, [dailyReportItems]);
