  // Helper Siklus Survey 360° Bulanan (H-7 s.d. H-3 Sebelum Tutup Buku)
  const getSurvey360Schedule = (cutoffDate: number, currentDay: number = 18) => {
    let openDay = cutoffDate - 7;
    if (openDay <= 0) openDay += 30;
    let deadlineDay = cutoffDate - 3;
    if (deadlineDay <= 0) deadlineDay += 30;

    let isOpen = false;
    if (openDay <= deadlineDay) {
      isOpen = currentDay >= openDay && currentDay <= deadlineDay;
    } else {
      isOpen = currentDay >= openDay || currentDay <= deadlineDay;
    }

    const isPastDeadline = currentDay > deadlineDay;
    const daysRemaining = isOpen ? Math.max(0, deadlineDay - currentDay) : 0;

    return {
      openDay,
      deadlineDay,
      cutoffDate,
      isOpen,
      isPastDeadline,
      daysRemaining,
    };
  };

