  // Kalkulator Komponen Penggajian Berdasarkan Matriks yang Aktif & SOP 001/V/2025 & SOP-HR-005
  const calculateStaffSalary = (emp: PayrollStaffItem, matrix: PositionSalaryConfig[]) => {
    const pos = matrix.find((p) => p.key === emp.positionKey) || matrix[0];

    let baseSalary = (emp.customBaseSalary !== undefined && emp.customBaseSalary > 0)
      ? emp.customBaseSalary
      : (emp.tenureStatus === 'MAGANG_3_HARI'
          ? pos.baseSalaryMagang
          : emp.tenureStatus === 'UNDER_3_MONTHS'
            ? pos.baseSalaryUnder3M
            : pos.baseSalaryOver3M);

    const autoMeal = emp.daysWorked * pos.mealAllowanceDaily;
    const meal = (emp.customMealAllowance !== undefined && emp.customMealAllowance !== null && emp.customMealAllowance >= 0)
      ? emp.customMealAllowance
      : autoMeal;

    const lemburDailyRate = emp.tenureStatus === 'MAGANG_3_HARI' ? pos.overtimeDailyMagang : pos.overtimeDailyRegular;
    const autoOvertime = emp.tenureStatus === 'MAGANG_3_HARI'
      ? emp.daysWorked * lemburDailyRate
      : Math.min(emp.daysWorked * lemburDailyRate, pos.overtimeMonthlyCap);
    const overtime = (emp.customOvertime !== undefined && emp.customOvertime !== null && emp.customOvertime >= 0)
      ? emp.customOvertime
      : autoOvertime;

    const autoPosAllow = emp.tenureStatus === 'MAGANG_3_HARI' ? 0 : pos.positionAllowance;
    const posAllow = (emp.customPositionAllowance !== undefined && emp.customPositionAllowance !== null && emp.customPositionAllowance >= 0)
      ? emp.customPositionAllowance
      : autoPosAllow;
    const jobAllow = emp.tenureStatus === 'MAGANG_3_HARI' ? 0 : pos.jobAllowance;
    const famAllow = (emp.isMarried && emp.tenureStatus !== 'MAGANG_3_HARI') ? pos.familyAllowance : 0;

    // SOP-HR-005: Skema Tunjangan Lama Bekerja Berdasarkan Masa Kerja:
    // Bulan 1 - 6: Rp 0
    // Bulan 7 - 12: Rp 100.000 / bulan
    // Bulan 13 - 18: Rp 200.000 / bulan (+ Rp 100.000)
    // Bulan 19 - 24: Rp 250.000 / bulan (+ Rp 50.000)
    // Bulan 25 - 30: Rp 300.000 / bulan (+ Rp 50.000)
    // Setiap kelipatan 6 bulan seterusnya: bertambah Rp 50.000 kumulatif
    const calculateTenureAllowance = (months: number): number => {
      if (!months || months <= 6) return 0;
      if (months <= 12) return 100000;
      if (months <= 18) return 200000;
      const extraSteps = Math.floor((months - 19) / 6) + 1;
      return 200000 + (extraSteps * 50000);
    };

    const tenureAllow = emp.monthsWorked !== undefined
      ? calculateTenureAllowance(emp.monthsWorked)
      : (emp.tenureStatus === 'SENIOR_6_MONTHS' ? 100000 : 0);

    // SOP Libur 001/V/2025 Pasal 2.3: Insentif tidak mengambil libur Rp 75.000 / hari (Maks Rp 150.000)
    const offIncentive = Math.min((emp.unusedOffDays || 0) * 75000, 150000);

    // SOP Libur 001/V/2025 Pasal 3.1 & 3.2: Denda pelanggaran libur (Weekend / Kelebihan / Beruntun)
    const offPenalty = emp.offViolationPenalty || 0;
    const stockFine = emp.stockFineDeduction || 0;

    // SOP Insentif KPI: Grade A = Rp 100.000, setelahnya (B/C/D) = Rp 0
    const kpiIncentive = (emp.kpiIncentive !== undefined)
      ? emp.kpiIncentive
      : (emp.kpiGrade === 'A' || (emp.kpiScore !== undefined && emp.kpiScore >= 90) ? 100000 : 0);

    // SOP-HR-006: Potongan Cuti Unpaid / Izin Di Luar Tanggungan (Prorata Upah Pokok / 30 hari)
    const dailyProrataRate = Math.round(baseSalary / 30);
    const unpaidDays = emp.unpaidLeaveDays || 0;
    const unpaidLeaveDeduction = unpaidDays * dailyProrataRate;

    // SOP-HR-007: Hak Cuti Tahunan Berjenjang Berdasarkan Masa Kerja (Masa Kerja >= 12 Bulan)
    // Formula: 1 thn = 1 hari, 2 thn = 2 hari, dst. Upah terhitung 100% tanpa potongan pokok.
    const annualLeaveQuota = emp.monthsWorked ? Math.floor(emp.monthsWorked / 12) : 0;
    const annualLeaveDays = emp.annualLeaveDays || 0;

    // SOP Bab 5: Penyesuaian Izin Pulang Setengah Hari (> 50% jam kerja weekday: gaji pokok harian tetap dapat, uang makan & lembur ditiadakan)
    const halfDays = emp.halfDayLeaveDays || 0;
    const halfDayMealDeduction = halfDays * pos.mealAllowanceDaily;
    const finalMeal = Math.max(meal - halfDayMealDeduction, 0);

    const halfDayOvertimeDeduction = halfDays * lemburDailyRate;
    const finalOvertime = Math.max(overtime - halfDayOvertimeDeduction, 0);

    const halfDayPenalty = emp.halfDayPenalties || 0;

    // SOP Resign Tengah Jalan (Wanprestasi PKWT / CLS-008): Gaji, tunjangan & pesangon hangus (Net Rp 0)
    const isResignEarly = emp.paymentStatus === 'HANGUS_RESIGN_SEPIHAK';

    const totalIncome = baseSalary + finalMeal + finalOvertime + posAllow + jobAllow + famAllow + tenureAllow + offIncentive + emp.bonusAdjustment + kpiIncentive;
    const totalDeduction = emp.kasbonDeduction + emp.penaltyDeduction + offPenalty + stockFine + unpaidLeaveDeduction + halfDayPenalty;
    const netPay = isResignEarly ? 0 : Math.max(totalIncome - totalDeduction, 0);

    return {
      pos,
      baseSalary,
      meal: finalMeal,
      overtime: finalOvertime,
      posAllow,
      jobAllow,
      famAllow,
      tenureAllow,
      offIncentive,
      offPenalty,
      stockFineDeduction: stockFine,
      unpaidLeaveDays: unpaidDays,
      unpaidLeaveDeduction,
      annualLeaveQuota,
      annualLeaveDays,
      halfDayLeaveDays: halfDays,
      halfDayMealDeduction,
      halfDayOvertimeDeduction,
      halfDayPenalty,
      kasbonDeduction: emp.kasbonDeduction,
      penaltyDeduction: emp.penaltyDeduction,
      kpiIncentive,
      totalIncome,
      totalDeduction,
      netPay,
      isResignEarly,
    };
  };

