  const [breakStaffList, setBreakStaffList] = useState(initialBreakStaff);
  const [breakRandomCounter, setBreakRandomCounter] = useState(1);

  // Algoritma Generator Acak Jadwal Istirahat dengan Ketentuan Wajib:
  // 1. Wajib ada bagian Produksi di setiap kloter
  // 2. Wajib ada bagian Waiters di setiap kloter
  // 3. Wajib ada Kasir atau Karyawan Perempuan di setiap kloter
  // 4. Rentang jam: 12:00 s/d 18:00 WIB (4 Kloter Bergantian)
  const handleRandomizeBreakSchedule = () => {
    const shuffle = <T,>(arr: T[]): T[] => {
      const copy = [...arr];
      for (let i = copy.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [copy[i], copy[j]] = [copy[j], copy[i]];
      }
      return copy;
    };

    const slots = [1, 2, 3, 4];
    const assignments: Record<string, number> = {};

    // 1. Pool staf Produksi
    const poolProduksi = shuffle(breakStaffList.filter((s) => s.department.includes('Produksi')));
    // 2. Pool staf Waiters
    const poolWaiters = shuffle(breakStaffList.filter((s) => s.department.includes('Waiters')));
    // 3. Pool staf Kasir atau Karyawan Perempuan
    const poolFemaleOrCashier = shuffle(breakStaffList.filter((s) => s.gender === 'Perempuan' || s.isCashier));

    // Pastikan tiap kloter (1 s/d 4) dapat 1 Produksi
    slots.forEach((slot, idx) => {
      if (poolProduksi[idx]) {
        assignments[poolProduksi[idx].id] = slot;
      }
    });

    // Pastikan tiap kloter (1 s/d 4) dapat 1 Waiters
    slots.forEach((slot, idx) => {
      if (poolWaiters[idx]) {
        assignments[poolWaiters[idx].id] = slot;
      }
    });

    // Pastikan tiap kloter memiliki Kasir atau Karyawan Perempuan
    slots.forEach((slot) => {
      const assignedToSlot = Object.keys(assignments).filter((id) => assignments[id] === slot);
      const hasFemaleOrCashier = assignedToSlot.some((id) => {
        const staff = breakStaffList.find((s) => s.id === id);
        return staff && (staff.gender === 'Perempuan' || staff.isCashier);
      });

      if (!hasFemaleOrCashier) {
        const candidate = poolFemaleOrCashier.find((s) => !assignments[s.id]);
        if (candidate) {
          assignments[candidate.id] = slot;
        }
      }
    });

    // Distribusikan sisa staf secara merata dan acak
    const unassigned = shuffle(breakStaffList.filter((s) => !assignments[s.id]));
    unassigned.forEach((staff) => {
      const slotCounts = slots.map((sl) => ({
        slot: sl,
        count: Object.values(assignments).filter((val) => val === sl).length,
      }));
      slotCounts.sort((a, b) => a.count - b.count);
      assignments[staff.id] = slotCounts[0].slot;
    });

    const updated = breakStaffList.map((s) => ({
      ...s,
      slotId: assignments[s.id] || 1,
    }));

    setBreakStaffList(updated);
    setBreakRandomCounter((prev) => prev + 1);
    showToast(
      '🎲 Jadwal Istirahat Bergantian (12:00 - 18:00 WIB) berhasil diacak otomatis dengan kepatuhan: Produksi ✓ Waiters ✓ Kasir/Perempuan ✓'
    );
  };

