  // Algoritma Analisis DISC
  const analyzeDiscAnswers = (answers: Record<number, 'D' | 'I' | 'S' | 'C'>) => {
    const counts = { D: 0, I: 0, S: 0, C: 0 };
    Object.values(answers).forEach((val) => {
      if (counts[val] !== undefined) counts[val]++;
    });

    const total = Object.values(answers).length || 20;
    const percentages = {
      D: Math.round((counts.D / total) * 100),
      I: Math.round((counts.I / total) * 100),
      S: Math.round((counts.S / total) * 100),
      C: Math.round((counts.C / total) * 100),
    };

    const traits: ('D' | 'I' | 'S' | 'C')[] = ['D', 'I', 'S', 'C'];
    const sorted = traits.sort((a, b) => counts[b] - counts[a]);
    const primaryTrait = sorted[0];
    const secondaryTrait = sorted[1];
    const profileCode = `${primaryTrait}${counts[secondaryTrait] >= 5 ? secondaryTrait : ''}`;

    let profileTitle = '';
    let summary = '';
    let strengths: string[] = [];
    let developmentAreas: string[] = [];
    let careerRecommendation = '';
    let badgeColor = '';

    switch (primaryTrait) {
      case 'D':
        profileTitle = secondaryTrait === 'I'
          ? 'The Persuasive Driver (Pemimpin Karismatik & Taktis)'
          : secondaryTrait === 'C'
          ? 'The Strategic Architect (Pemimpin Tegas & Berstandar Tinggi)'
          : 'The Commander (Pemimpin Taktis & Eksekutor Hasil)';
        summary = 'Berani mengambil risiko, cepat dalam mengambil keputusan saat jam sibuk resto, berorientasi kuat pada target omzet dan efisiensi operasional.';
        strengths = ['Mengendalikan situasi kritis saat rush hour', 'Tegas dalam pendelegasian tugas stasiun', 'Fokus pada pencapaian target omzet & kecepatan saji'];
        developmentAreas = ['Perlu meningkatkan kesabaran saat melatih kru baru', 'Belajar mendengar masukan kru sebelum memutuskan'];
        careerRecommendation = counts.D >= 10 && counts.C >= 4
          ? 'Jalur Promosi Teratas: Supervisor Operasional Area (di atas Kepala Cabang)'
          : counts.D >= 7 && counts.I >= 4
          ? 'Jalur Kepemimpinan: Kepala Cabang (Branch Manager) atau Asisten Supervisor'
          : 'Jalur Kepemimpinan: Kepala Cabang Resto';
        badgeColor = 'bg-rose-100 text-rose-800 border-rose-300';
        break;

      case 'I':
        profileTitle = secondaryTrait === 'D'
          ? 'The Inspiring Pioneer (Penggerak Tim & Pelopor)'
          : 'The Influencer (Pembangun Antusiasme & Hospitality Hero)';
        summary = 'Sangat ramah, komunikatif, ekspresif, ahli dalam membangun atmosfer kerja ceria dan memikat hati pelanggan di area meja makan.';
        strengths = ['Kemampuan komunikasi & upselling menu luar biasa', 'Menciptakan suasana kerja yang menyenangkan dan kompak', 'Ahli dalam service recovery & meredakan komplain tamu dengan ramah'];
        developmentAreas = ['Disiplin pada kerapian catatan stok & detail kasir', 'Fokus menyelesaikan satu tugas sebelum berpindah ke hal lain'];
        careerRecommendation = 'Posisi Ideal: Captain Service (Supervisor Service FOH), Public Relations Toko, atau Duta Hospitality Pelanggan';
        badgeColor = 'bg-amber-100 text-amber-900 border-amber-300';
        break;

      case 'S':
        profileTitle = secondaryTrait === 'C'
          ? 'The Quality Anchor (Penjaga Standar & Ketertiban Dapur)'
          : 'The Steady Anchor (Eksekutor Sabar, Konsisten & Setia)';
        summary = 'Sabar, konsisten, pendengar yang baik, sangat tenang di bawah rutinitas harian dapur, dan loyal terhadap keharmonisan tim kerja.';
        strengths = ['Konsistensi rasa masakan dan ketahanan di stasiun kerja', 'Rekan kerja yang sangat suportif dan minim konflik', 'Sabar membimbing kru magang langkah demi langkah'];
        developmentAreas = ['Belajar lebih berani menyuarakan pendapat dan ide perubahan', 'Mempersiapkan diri saat terjadi perubahan shift mendadak'];
        careerRecommendation = 'Posisi Ideal: Head Kitchen (Supervisor Dapur BOH), Juru Masak Utama (Main Cook Station), atau Koordinator Helper';
        badgeColor = 'bg-emerald-100 text-emerald-800 border-emerald-300';
        break;

      case 'C':
        profileTitle = secondaryTrait === 'D'
          ? 'The Systematic Controller (Pengendali Mutu & Auditor)'
          : 'The Precisionist (Penegak Standar Resep, QC & Akurasi Keuangan)';
        summary = 'Sangat teliti, sistematis, patuh 100% pada gramatur bumbu, higienitas HACCP, dan presisi dalam pembukuan kas laci harian.';
        strengths = ['Akurasi penghitungan kasir dan rekonsiliasi kas harian', 'Penegakan standar sanitasi dan Food Safety HACCP', 'Pengendalian HPP, waste log, dan pencegahan selisih stok'];
        developmentAreas = ['Belajar lebih fleksibel ketika menghadapi situasi darurat di lapangan', 'Hindari overthinking saat butuh keputusan cepat'];
        careerRecommendation = 'Posisi Ideal: Asisten Supervisor (Audit Kepatuhan & Mutu), Kasir Audit Closing, atau Inventory Controller Cabang';
        badgeColor = 'bg-indigo-100 text-indigo-800 border-indigo-300';
        break;
    }

    return {
      primaryTrait,
      secondaryTrait,
      profileCode,
      profileTitle,
      scores: counts,
      percentages,
      summary,
      strengths,
      developmentAreas,
      careerRecommendation,
      badgeColor,
    };
  };

  // =========================================================
  // KOMPONEN VISUALISASI GRAFIK RADAR & DONUT CHART DISC
  // =========================================================
  interface DiscChartVisualizerProps {
    percentages: { D: number; I: number; S: number; C: number };
    dominantTrait?: 'D' | 'I' | 'S' | 'C';
    profileCode?: string;
    size?: 'sm' | 'md' | 'lg';
    defaultMode?: 'radar' | 'donut';
    showToggle?: boolean;
    theme?: 'light' | 'dark';
  }

  const DiscChartVisualizer = ({
    percentages,
    dominantTrait = 'D',
    profileCode = 'DISC',
    size = 'md',
    defaultMode = 'radar',
    showToggle = true,
    theme = 'light',
  }: DiscChartVisualizerProps) => {
    const [chartMode, setChartMode] = useState<'radar' | 'donut'>(defaultMode);

    const pD = Math.max(5, Math.min(100, percentages.D || 0));
    const pI = Math.max(5, Math.min(100, percentages.I || 0));
    const pS = Math.max(5, Math.min(100, percentages.S || 0));
    const pC = Math.max(5, Math.min(100, percentages.C || 0));

    // Dimensi Radar
    const config = size === 'sm'
      ? { vb: '0 0 180 180', cx: 90, cy: 90, maxR: 56, fontSize: '9px', circleR: 3.5 }
      : size === 'lg'
      ? { vb: '0 0 240 240', cx: 120, cy: 120, maxR: 82, fontSize: '11px', circleR: 5 }
      : { vb: '0 0 210 210', cx: 105, cy: 105, maxR: 70, fontSize: '10px', circleR: 4.5 };

    const { cx, cy, maxR, vb, fontSize, circleR } = config;

    // Titik Radar
    const xD = cx;
    const yD = cy - (pD / 100) * maxR;
    const xI = cx + (pI / 100) * maxR;
    const yI = cy;
    const xS = cx;
    const yS = cy + (pS / 100) * maxR;
    const xC = cx - (pC / 100) * maxR;
    const yC = cy;

    // Dimensi Donut
    const donutR = size === 'sm' ? 40 : size === 'lg' ? 62 : 50;
    const donutCircumference = 2 * Math.PI * donutR;
    const donutStroke = size === 'sm' ? 14 : size === 'lg' ? 22 : 18;
    const donutCenter = size === 'sm' ? 65 : size === 'lg' ? 95 : 80;
    const donutVb = size === 'sm' ? '0 0 130 130' : size === 'lg' ? '0 0 190 190' : '0 0 160 160';

    const offD = 0;
    const offI = -((pD / 100) * donutCircumference);
    const offS = -(((pD + pI) / 100) * donutCircumference);
    const offC = -(((pD + pI + pS) / 100) * donutCircumference);

    const isDark = theme === 'dark';

    return (
      <div className="flex flex-col items-center w-full">
        {showToggle && (
          <div className={`flex items-center p-1 rounded-xl mb-3 text-xs font-bold ${isDark ? 'bg-white/10' : 'bg-slate-100'}`}>
            <button
              type="button"
              onClick={() => setChartMode('radar')}
              className={`px-2.5 py-1 rounded-lg transition flex items-center gap-1 ${
                chartMode === 'radar'
                  ? isDark ? 'bg-purple-600 text-white shadow-xs' : 'bg-white text-purple-900 shadow-xs'
                  : isDark ? 'text-slate-300 hover:text-white' : 'text-slate-600 hover:text-slate-900'
              }`}
            >
              <span>🕸️</span>
              <span>Grafik Radar</span>
            </button>
            <button
              type="button"
              onClick={() => setChartMode('donut')}
              className={`px-2.5 py-1 rounded-lg transition flex items-center gap-1 ${
                chartMode === 'donut'
                  ? isDark ? 'bg-purple-600 text-white shadow-xs' : 'bg-white text-purple-900 shadow-xs'
                  : isDark ? 'text-slate-300 hover:text-white' : 'text-slate-600 hover:text-slate-900'
              }`}
            >
              <span>🍩</span>
              <span>Pie / Donut</span>
            </button>
          </div>
        )}

        {chartMode === 'radar' ? (
          <div className="relative flex items-center justify-center w-full py-1">
            <svg viewBox={vb} className="w-full max-w-[210px] aspect-square overflow-visible">
              {/* Concentric grid webs */}
              {[0.25, 0.5, 0.75, 1.0].map((level, idx) => {
                const r = maxR * level;
                return (
                  <polygon
                    key={idx}
                    points={`${cx},${cy - r} ${cx + r},${cy} ${cx},${cy + r} ${cx - r},${cy}`}
                    fill={idx === 3 ? (isDark ? 'rgba(255,255,255,0.03)' : 'rgba(241,245,249,0.5)') : 'none'}
                    stroke={isDark ? 'rgba(255,255,255,0.18)' : '#e2e8f0'}
                    strokeWidth="1"
                    strokeDasharray={idx < 3 ? '2 2' : 'none'}
                  />
                );
              })}

              {/* Cross Axis lines */}
              <line x1={cx} y1={cy - maxR - 4} x2={cx} y2={cy + maxR + 4} stroke={isDark ? 'rgba(255,255,255,0.22)' : '#cbd5e1'} strokeWidth="1" />
              <line x1={cx - maxR - 4} y1={cy} x2={cx + maxR + 4} y2={cy} stroke={isDark ? 'rgba(255,255,255,0.22)' : '#cbd5e1'} strokeWidth="1" />

              {/* Radar Value Polygon */}
              <polygon
                points={`${xD},${yD} ${xI},${yI} ${xS},${yS} ${xC},${yC}`}
                fill={isDark ? 'rgba(168, 85, 247, 0.4)' : 'rgba(147, 51, 234, 0.28)'}
                stroke="#9333ea"
                strokeWidth="2.5"
                strokeLinejoin="round"
              />

              {/* Coordinate Dots */}
              <circle cx={xD} cy={yD} r={circleR} fill="#f43f5e" stroke={isDark ? '#0f172a' : '#ffffff'} strokeWidth="2" />
              <circle cx={xI} cy={yI} r={circleR} fill="#f59e0b" stroke={isDark ? '#0f172a' : '#ffffff'} strokeWidth="2" />
              <circle cx={xS} cy={yS} r={circleR} fill="#10b981" stroke={isDark ? '#0f172a' : '#ffffff'} strokeWidth="2" />
              <circle cx={xC} cy={yC} r={circleR} fill="#6366f1" stroke={isDark ? '#0f172a' : '#ffffff'} strokeWidth="2" />

              {/* Axis Labels */}
              <text x={cx} y={cy - maxR - 10} textAnchor="middle" fill="#f43f5e" fontWeight="900" fontSize={fontSize}>
                D: {percentages.D}%
              </text>
              <text x={cx + maxR + 8} y={cy + 4} textAnchor="start" fill="#f59e0b" fontWeight="900" fontSize={fontSize}>
                I: {percentages.I}%
              </text>
              <text x={cx} y={cy + maxR + 18} textAnchor="middle" fill="#10b981" fontWeight="900" fontSize={fontSize}>
                S: {percentages.S}%
              </text>
              <text x={cx - maxR - 8} y={cy + 4} textAnchor="end" fill="#6366f1" fontWeight="900" fontSize={fontSize}>
                C: {percentages.C}%
              </text>
            </svg>
          </div>
        ) : (
          <div className="relative flex items-center justify-center w-full py-1">
            <svg viewBox={donutVb} className="w-full max-w-[190px] aspect-square">
              {/* Background track */}
              <circle
                cx={donutCenter}
                cy={donutCenter}
                r={donutR}
                fill="none"
                stroke={isDark ? 'rgba(255,255,255,0.08)' : '#f1f5f9'}
                strokeWidth={donutStroke}
              />

              {/* Arc D */}
              <circle
                cx={donutCenter}
                cy={donutCenter}
                r={donutR}
                fill="none"
                stroke="#f43f5e"
                strokeWidth={donutStroke}
                strokeDasharray={`${(pD / 100) * donutCircumference} ${donutCircumference}`}
                strokeDashoffset={offD}
                transform={`rotate(-90 ${donutCenter} ${donutCenter})`}
              />

              {/* Arc I */}
              <circle
                cx={donutCenter}
                cy={donutCenter}
                r={donutR}
                fill="none"
                stroke="#f59e0b"
                strokeWidth={donutStroke}
                strokeDasharray={`${(pI / 100) * donutCircumference} ${donutCircumference}`}
                strokeDashoffset={offI}
                transform={`rotate(-90 ${donutCenter} ${donutCenter})`}
              />

              {/* Arc S */}
              <circle
                cx={donutCenter}
                cy={donutCenter}
                r={donutR}
                fill="none"
                stroke="#10b981"
                strokeWidth={donutStroke}
                strokeDasharray={`${(pS / 100) * donutCircumference} ${donutCircumference}`}
                strokeDashoffset={offS}
                transform={`rotate(-90 ${donutCenter} ${donutCenter})`}
              />

              {/* Arc C */}
              <circle
                cx={donutCenter}
                cy={donutCenter}
                r={donutR}
                fill="none"
                stroke="#6366f1"
                strokeWidth={donutStroke}
                strokeDasharray={`${(pC / 100) * donutCircumference} ${donutCircumference}`}
                strokeDashoffset={offC}
                transform={`rotate(-90 ${donutCenter} ${donutCenter})`}
              />

              {/* Center text badge */}
              <text
                x={donutCenter}
                y={donutCenter - 4}
                textAnchor="middle"
                className={`font-black ${isDark ? 'fill-white' : 'fill-slate-900'}`}
                fontSize={size === 'sm' ? '12px' : '15px'}
              >
                {profileCode || dominantTrait}
              </text>
              <text
                x={donutCenter}
                y={donutCenter + 12}
                textAnchor="middle"
                className="font-bold fill-purple-400"
                fontSize={size === 'sm' ? '8px' : '9px'}
              >
                PROFIL DISC
              </text>
            </svg>
          </div>
        )}

        {/* Legend 4 Kuadran */}
        <div className="grid grid-cols-2 gap-x-3 gap-y-1 mt-2 text-[10px] font-bold">
          <div className="flex items-center gap-1.5">
            <span className="w-2.5 h-2.5 rounded-full bg-rose-500 shrink-0" />
            <span className={isDark ? 'text-rose-300' : 'text-rose-700'}>Dominance: {percentages.D}%</span>
          </div>
          <div className="flex items-center gap-1.5">
            <span className="w-2.5 h-2.5 rounded-full bg-amber-500 shrink-0" />
            <span className={isDark ? 'text-amber-300' : 'text-amber-700'}>Influence: {percentages.I}%</span>
          </div>
          <div className="flex items-center gap-1.5">
            <span className="w-2.5 h-2.5 rounded-full bg-emerald-500 shrink-0" />
            <span className={isDark ? 'text-emerald-300' : 'text-emerald-700'}>Steadiness: {percentages.S}%</span>
          </div>
          <div className="flex items-center gap-1.5">
            <span className="w-2.5 h-2.5 rounded-full bg-indigo-500 shrink-0" />
            <span className={isDark ? 'text-indigo-300' : 'text-indigo-700'}>Conscientiousness: {percentages.C}%</span>
          </div>
        </div>
      </div>
    );
  };

