  const [permissionMatrix, setPermissionMatrix] = useState<Record<string, Record<string, boolean>>>(initialPermissionMatrix);

  const togglePermission = (permKey: string, roleKey: string) => {
    setPermissionMatrix((prev) => {
      const currentVal = prev[permKey]?.[roleKey] ?? false;
      return {
        ...prev,
        [permKey]: {
          ...prev[permKey],
          [roleKey]: !currentVal,
        },
      };
    });
  };

