  interface TimesheetDayRecord {
    day: number;
    status: 'H' | 'T' | 'L' | 'S' | 'I' | 'A' | 'SCH';
    clockIn?: string;
    clockOut?: string;
    lateMinutes?: number;
    faceScore?: number;
    landmarks?: string;
    note?: string;
  }

  interface StaffTimesheetRow {
    id: string;
    name: string;
    nik: string;
    position: string;
    department: 'Produksi (Kitchen BOH)' | 'Layanan (Service FOH)' | 'Kasir & Billing';
    outlet: string;
    avatar: string;
    records: Record<number, TimesheetDayRecord>;
  }

  const octDaysList = Array.from({ length: 31 }, (_, i) => {
    const day = i + 1;
    const dayNames = ['Min', 'Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab'];
    // 2026-10-01 is Thursday (index 4)
    const dIndex = (4 + (day - 1)) % 7;
    const isWeekend = dIndex === 0 || dIndex === 6;
    const isToday = day === 17;
    const isPastOrToday = day <= 17;
    return {
      day,
      dayName: dayNames[dIndex],
      isWeekend,
      isToday,
      isPastOrToday,
    };
  });

  const createDefaultStaffRecords = (
    offDays: number[],
    lateDays: { day: number; lateMinutes: number; time: string; note: string }[],
    specialDays: { day: number; status: 'S' | 'I' | 'A'; note: string }[] = []
  ): Record<number, TimesheetDayRecord> => {
    const records: Record<number, TimesheetDayRecord> = {};
    for (let d = 1; d <= 31; d++) {
      if (d > 17) {
        if (offDays.includes(d)) {
          records[d] = { day: d, status: 'L', note: 'Jadwal Libur Terencana (SOP-001)' };
        } else {
          records[d] = { day: d, status: 'SCH', clockIn: '09:00 WIB', clockOut: '22:30 WIB', note: 'Shift Roster Terjadwal' };
        }
      } else {
        const special = specialDays.find((s) => s.day === d);
        if (special) {
          records[d] = {
            day: d,
            status: special.status,
            note: special.note,
          };
          continue;
        }

        if (offDays.includes(d)) {
          records[d] = {
            day: d,
            status: 'L',
            note: 'Libur Resmi Terjadwal Sesuai SOP-001 (2 Hari/Bulan)',
          };
          continue;
        }

        const late = lateDays.find((l) => l.day === d);
        if (late) {
          records[d] = {
            day: d,
            status: 'T',
            clockIn: late.time,
            clockOut: '22:30 WIB',
            lateMinutes: late.lateMinutes,
            faceScore: 98,
            landmarks: 'Oval Wajah, 2 Mata, Hidung, Bibir Valid',
            note: late.note,
          };
        } else {
          records[d] = {
            day: d,
            status: 'H',
            clockIn: d === 17 ? '08:48 WIB' : '08:52 WIB',
            clockOut: d === 17 ? 'Sedang Bertugas' : '22:30 WIB',
            lateMinutes: 0,
            faceScore: 99,
            landmarks: 'Oval Wajah, 2 Mata, Hidung, Bibir Valid',
            note: 'Hadir Tepat Waktu • Verifikasi Biometrik Lolos 100%',
          };
        }
      }
    }
    return records;
  };

