                        const q = clauseSearchQuery.toLowerCase();
                        return (
                          c.title.toLowerCase().includes(q) ||
                          c.category.toLowerCase().includes(q) ||
                          c.text.toLowerCase().includes(q) ||
                          (c.legalReference && c.legalReference.toLowerCase().includes(q))
                        );
